function wmo(c){if(c==null)return["No forecast","cloud"];if(c===0)return["Clear","sun"];if(c<=2)return["Partly cloudy","psun"];if(c===3)return["Overcast","cloud"];if(c<=48)return["Fog","fog"];if(c<=57)return["Drizzle","rain"];if(c<=67)return["Rain","rain"];if(c<=77)return["Snow","snow"];if(c<=82)return["Showers","rain"];if(c<=86)return["Snow showers","snow"];return["Thunderstorm","storm"]}

/* ===================== storage (IndexedDB, localStorage fallback) ===================== */
const DBN="wayfarer",DBV=1;let idb=null,STORE="idb",MEM={};
function lsOK(){try{localStorage.setItem("wf:t","1");localStorage.removeItem("wf:t");return true}catch(e){return false}}
function openDB(){return new Promise(res=>{try{if(!window.indexedDB)throw 0;const r=indexedDB.open(DBN,DBV);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains("kv"))d.createObjectStore("kv");if(!d.objectStoreNames.contains("photos"))d.createObjectStore("photos")};r.onsuccess=()=>{idb=r.result;res(idb)};r.onerror=()=>res(null);r.onblocked=()=>res(null)}catch(e){res(null)}}).then(d=>{if(!d)STORE=lsOK()?"ls":"mem";return d})}
function kvGet(store,k){return new Promise(res=>{if(!idb){if(STORE==="mem"){res(MEM[store+":"+k]??null);return}try{res(JSON.parse(localStorage.getItem("wf:"+store+":"+k)))}catch(e){res(null)}return}try{const t=idb.transaction(store,"readonly").objectStore(store).get(k);t.onsuccess=()=>res(t.result??null);t.onerror=()=>res(null)}catch(e){res(null)}})}
function kvSet(store,k,v){return new Promise(res=>{if(!idb){if(STORE==="mem"){MEM[store+":"+k]=v;res();return}if(v instanceof Blob){res();return}try{localStorage.setItem("wf:"+store+":"+k,JSON.stringify(v))}catch(e){}res();return}try{const t=idb.transaction(store,"readwrite");t.objectStore(store).put(v,k);t.oncomplete=()=>res();t.onerror=()=>res()}catch(e){res()}})}
function kvDel(store,k){return new Promise(res=>{if(!idb){delete MEM[store+":"+k];try{localStorage.removeItem("wf:"+store+":"+k)}catch(e){}res();return}try{const t=idb.transaction(store,"readwrite");t.objectStore(store).delete(k);t.oncomplete=()=>res();t.onerror=()=>res()}catch(e){res()}})}
function kvClear(){return new Promise(res=>{try{Object.keys(localStorage).filter(k=>k.startsWith("wf:")).forEach(k=>localStorage.removeItem(k))}catch(e){}if(!idb){res();return}try{const t=idb.transaction(["kv","photos"],"readwrite");t.objectStore("kv").clear();t.objectStore("photos").clear();t.oncomplete=()=>res();t.onerror=()=>res()}catch(e){res()}})}

/* ===================== state ===================== */
let S=null;const defaults=()=>({v:1,settings:{theme:"auto",rates:{PLN:4.28,CHF:0.94,GBP:0.85,USD:1.08},autolock:5,homeCur:"EUR",seeded:0},trips:{},active:null,journey:{},wxcache:{}});
let saveT=null;function save(){clearTimeout(saveT);saveT=setTimeout(()=>kvSet("kv","state",S),250)}
function validTrip(t){return t&&typeof t==="object"&&typeof t.id==="string"&&/^[\w-]{1,40}$/.test(t.id)&&typeof t.name==="string"&&/^\d{4}-\d{2}-\d{2}$/.test(t.from||"")&&/^\d{4}-\d{2}-\d{2}$/.test(t.to||"")&&Array.isArray(t.cities)&&t.days&&typeof t.days==="object"}
const normAct=a=>({id:/^[\da-f]{16}$/.test(a.id||"")?a.id:uid(),t:String(a.t||"").slice(0,12),title:String(a.title||"").slice(0,120),cat:CATS[a.cat]?a.cat:"other",note:String(a.note||"").slice(0,600),place:String(a.place||"").slice(0,120),lat:isFinite(+a.lat)&&a.lat!==null?+a.lat:null,lon:isFinite(+a.lon)&&a.lon!==null?+a.lon:null,cost:+a.cost||0,cur:/^[A-Z]{3}$/.test(a.cur||"")?a.cur:"EUR",booked:String(a.booked||"").slice(0,20),done:!!a.done,link:safeUrl(a.link||""),wiki:String(a.wiki||"").slice(0,120)});
function normOptions(o){const out={};if(!o||typeof o!=="object")return out;for(const k of Object.keys(o)){if(!/^\d{4}-\d{2}-\d{2}$/.test(k)||!Array.isArray(o[k]))continue;out[k]=o[k].filter(x=>x&&typeof x==="object"&&typeof x.id==="string").slice(0,8).map(x=>({id:String(x.id).slice(0,40),name:String(x.name||"").slice(0,80),prof:["in","out","mix"].includes(x.prof)?x.prof:"mix",km:+x.km||0,tmin:+x.tmin||0,hrs:+x.hrs||4,why:String(x.why||"").slice(0,300),needs:Object.fromEntries(["dry","daylight","noSnow","clear"].filter(n=>x.needs&&x.needs[n]).map(n=>[n,true])),closed:(Array.isArray(x.closed)?x.closed:[]).map(Number).filter(n=>n>=0&&n<=6),fixed:!!x.fixed,acts:(Array.isArray(x.acts)?x.acts:[]).slice(0,20).map(normAct)}))}return out}
function normTrip(t){t.name=String(t.name).slice(0,80);t.sub=String(t.sub||"").slice(0,120);t.cities=t.cities.filter(c=>c&&typeof c.name==="string").map(c=>({name:String(c.name).slice(0,60),lat:+c.lat||null,lon:+c.lon||null,country:String(c.country||"").slice(0,3),arrive:c.arrive||t.from,depart:c.depart||t.to,stay:String(c.stay||"").slice(0,120),wiki:String(c.wiki||"").slice(0,120),station:String(c.station||"").slice(0,60),slat:+c.slat||null,slon:+c.slon||null}));
 const days={};for(const k of Object.keys(t.days)){if(!/^\d{4}-\d{2}-\d{2}$/.test(k))continue;const d=t.days[k]||{};days[k]={title:String(d.title||"").slice(0,80),city:String(d.city||"").slice(0,60),chosen:String(d.chosen||"").slice(0,40),acts:(Array.isArray(d.acts)?d.acts:[]).map(a=>({id:/^[\da-f]{16}$/.test(a.id||"")?a.id:uid(),t:String(a.t||"").slice(0,12),title:String(a.title||"").slice(0,120),cat:CATS[a.cat]?a.cat:"other",note:String(a.note||"").slice(0,600),place:String(a.place||"").slice(0,120),lat:isFinite(+a.lat)&&a.lat!==null?+a.lat:null,lon:isFinite(+a.lon)&&a.lon!==null?+a.lon:null,cost:+a.cost||0,cur:/^[A-Z]{3}$/.test(a.cur||"")?a.cur:"EUR",booked:String(a.booked||"").slice(0,20),done:!!a.done,link:safeUrl(a.link||""),wiki:String(a.wiki||"").slice(0,120)}))}}
 t.days=days;t.options=normOptions(t.options);t.budget={amount:+(t.budget&&t.budget.amount)||0,cur:/^[A-Z]{3}$/.test(t.budget&&t.budget.cur||"")?t.budget.cur:"EUR"};
 t.expenses=(Array.isArray(t.expenses)?t.expenses:[]).map(e=>({id:/^[\da-f]{16}$/.test(e.id||"")?e.id:uid(),date:/^\d{4}-\d{2}-\d{2}$/.test(e.date||"")?e.date:t.from,amount:+e.amount||0,cur:/^[A-Z]{3}$/.test(e.cur||"")?e.cur:"EUR",cat:String(e.cat||"other").slice(0,20),note:String(e.note||"").slice(0,120)}));
 t.journal=t.journal&&typeof t.journal==="object"?t.journal:{};for(const k of Object.keys(t.journal)){const j=t.journal[k]||{};t.journal[k]={text:String(j.text||"").slice(0,4000),photos:(Array.isArray(j.photos)?j.photos:[]).filter(p=>/^[\da-f]{16}$/.test(p))}}
 t.vault=t.vault&&typeof t.vault.ct==="string"&&typeof t.vault.iv==="string"&&typeof t.vault.salt==="string"?{ct:t.vault.ct,iv:t.vault.iv,salt:t.vault.salt,n:+t.vault.n||0}:null;
 t.pack=t.pack&&Array.isArray(t.pack.groups)?{groups:t.pack.groups.map(g=>({name:String(g.name||"").slice(0,60),items:(Array.isArray(g.items)?g.items:[]).map(i=>({id:/^[\da-f]{16}$/.test(i.id||"")?i.id:uid(),t:String(i.t||"").slice(0,100),note:String(i.note||"").slice(0,160),tag:String(i.tag||"").slice(0,20),done:!!i.done}))}))}:packTemplate("cold");
 t.notes=(Array.isArray(t.notes)?t.notes:[]).map(n=>[String(n[0]||"").slice(0,40),String(n[1]||"").slice(0,300)]);t.eat=(Array.isArray(t.eat)?t.eat:[]).map(e=>[String(e[0]||"").slice(0,40),(Array.isArray(e[1])?e[1]:[]).map(x=>String(x).slice(0,160))]);
 t.cover=String(t.cover||"").slice(0,120);t.home=String(t.home||"").slice(0,60);t.homeLat=+t.homeLat||null;t.homeLon=+t.homeLon||null;t.created=+t.created||Date.now();return t}
async function loadState(){await openDB();const saved=await kvGet("kv","state");S=defaults();if(saved&&saved.trips){S.settings=Object.assign(S.settings,saved.settings||{});S.active=saved.active||null;S.journey=saved.journey||{};S.wxcache=saved.wxcache||{};for(const k of Object.keys(saved.trips)){const t=saved.trips[k];if(validTrip(t))S.trips[t.id]=normTrip(t)}}
 if(S.settings.picv!==2){S.settings.picmiss={};S.settings.pics={};S.settings.picv=2}
 if(S.settings.seeded<SEED_VERSION){if(S.settings.seeded<5&&S.trips["poland-2026"]){const old=S.trips["poland-2026"],f=seedPoland();for(const k of ["days","options","cities","sub","notes","eat","name","cover","from","to"])old[k]=f[k];PLANDAY=null}if(!S.trips["poland-2026"])S.trips["poland-2026"]=seedPoland();if(!S.trips["alps-2026"])S.trips["alps-2026"]=seedAlpine();for(const id of ["poland-2026","alps-2026"]){const t=S.trips[id];if(!t)continue;const fresh=id==="poland-2026"?seedPoland():seedAlpine();if(!t.cover)t.cover=fresh.cover;t.cities.forEach(c=>{const f=fresh.cities.find(x=>x.name===c.name);if(f&&!c.wiki)c.wiki=f.wiki});for(const d of Object.keys(t.days))(t.days[d].acts||[]).forEach(x=>{if(!x.wiki&&WIKI[x.title])x.wiki=WIKI[x.title]})}S.settings.seeded=SEED_VERSION}
 if(!S.active||!S.trips[S.active])S.active=pickActive();save()}
function pickActive(){const t=todayISO(),list=Object.values(S.trips).sort((a,b)=>a.from.localeCompare(b.from));return (list.find(x=>x.from<=t&&x.to>=t)||list.find(x=>x.from>t)||list[list.length-1]||{id:null}).id}
const T=()=>S.trips[S.active];
const tripDays=t=>{const out=[];for(let d=t.from;d<=t.to;d=addDays(d,1))out.push(d);return out};
const dayOf=(t,d)=>t.days[d]||(t.days[d]={title:"",city:"",acts:[]});
const cityFor=(t,d)=>t.cities.find(c=>c.arrive<=d&&c.depart>=d)||t.cities[0];
const rate=cur=>cur===S.settings.homeCur?1:1/(S.settings.rates[cur]||1);
const toHome=(n,cur)=>n*rate(cur);

/* ===================== crypto vault (AES-GCM, PBKDF2) ===================== */
const te=new TextEncoder(),td=new TextDecoder();
const b64=b=>btoa(String.fromCharCode(...new Uint8Array(b)));const ub64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
const VAULT={key:null,items:null,timer:null};
async function deriveKey(pin,salt){const km=await crypto.subtle.importKey("raw",te.encode(pin),"PBKDF2",false,["deriveKey"]);return crypto.subtle.deriveKey({name:"PBKDF2",salt,iterations:310000,hash:"SHA-256"},km,{name:"AES-GCM",length:256},false,["encrypt","decrypt"])}
async function vaultSeal(items,key,saltB){const iv=crypto.getRandomValues(new Uint8Array(12));const ct=await crypto.subtle.encrypt({name:"AES-GCM",iv},key,te.encode(JSON.stringify({items,at:Date.now()})));return {ct:b64(ct),iv:b64(iv),salt:saltB,n:items.length}}
async function vaultOpen(v,key){const pt=await crypto.subtle.decrypt({name:"AES-GCM",iv:ub64(v.iv)},key,ub64(v.ct));return JSON.parse(td.decode(pt)).items}
function vaultLock(){VAULT.key=null;VAULT.items=null;clearTimeout(VAULT.timer)}
function vaultTouch(){clearTimeout(VAULT.timer);if(VAULT.key)VAULT.timer=setTimeout(()=>{vaultLock();if(location.hash==="#vault")render()},(S.settings.autolock||5)*60000)}
async function encryptBackup(json,pin){const salt=crypto.getRandomValues(new Uint8Array(16));const key=await deriveKey(pin,salt);const iv=crypto.getRandomValues(new Uint8Array(12));const ct=await crypto.subtle.encrypt({name:"AES-GCM",iv},key,te.encode(json));return JSON.stringify({wayfarer:"encrypted",v:1,salt:b64(salt),iv:b64(iv),ct:b64(ct)})}
async function decryptBackup(obj,pin){const key=await deriveKey(pin,ub64(obj.salt));const pt=await crypto.subtle.decrypt({name:"AES-GCM",iv:ub64(obj.iv)},key,ub64(obj.ct));return td.decode(pt)}

