/* ===================== router and shell ===================== */
const VIEWS=["home","plan","map","live","more","weather","budget","pack","journal","vault","settings","trips"];
const NAVMAP={home:"home",plan:"plan",map:"map",live:"live",more:"more",weather:"more",budget:"more",pack:"more",journal:"more",vault:"more",settings:"more",trips:"home"};
let VIEW="home";
function go(v){if(!VIEWS.includes(v))v="home";if(location.hash!=="#"+v)location.hash=v;else render()}
addEventListener("hashchange",render);
function render(){const v=(location.hash||"#home").slice(1);VIEW=VIEWS.includes(v)?v:"home";
 $$(".view").forEach(s=>s.classList.toggle("on",s.id==="v-"+VIEW));$$("#nav button").forEach(b=>b.classList.toggle("on",b.dataset.go===NAVMAP[VIEW]));
 const r={home:renderHome,plan:renderPlan,map:renderMap,live:renderLive,more:renderMore,weather:renderWeather,budget:renderBudget,pack:renderPack,journal:renderJournal,vault:renderVault,settings:renderSettings,trips:renderTrips}[VIEW];
 try{r()}catch(e){console.error(e);$("#v-"+VIEW).innerHTML=`<div class="empty"><b>Something went wrong</b>${esc(e.message)}</div>`}
 window.scrollTo({top:0})}
const topbar=(title,sub,right="")=>`<div class="top"><div class="brand">${esc(title)}<small>${esc(sub)}</small></div><div class="row">${right}</div></div>`;
const backBtn=(to="more")=>`<button class="ibtn" data-a="go" data-arg="${to}" aria-label="Back"><svg viewBox="0 0 24 24"><path d="M15 6l-6 6 6 6"/></svg></button>`;

