/* ===================== PLAN ===================== */
function actSheet(id){const t=T(),day=id?findDay(t,id):PLANDAY,a=id?dayOf(t,day).acts.find(x=>x.id===id):{t:"",title:"",cat:"sight",note:"",place:"",lat:null,lon:null,cost:0,cur:cityFor(t,day)&&cityFor(t,day).country==="PL"?"PLN":"EUR",booked:"",link:"",wiki:""};
 sheet(`<h2>${id?"Edit activity":"New activity"}</h2><form id="f-act" data-id="${id||""}" data-day="${day}">
 <div class="f"><label>Title</label><input name="title" required maxlength="120" value="${esc(a.title)}" placeholder="Wawel Royal Castle"></div>
 <div class="in2"><div class="f"><label>Time</label><input name="t" maxlength="12" value="${esc(a.t)}" placeholder="09:30"></div><div class="f"><label>Type</label><select name="cat">${Object.keys(CATN).map(k=>`<option value="${k}" ${k===a.cat?"selected":""}>${CATN[k]}</option>`).join("")}</select></div></div>
 <div class="f"><label>Place (for the map)</label><div class="row"><input name="place" maxlength="120" value="${esc(a.place)}" placeholder="Name of the place or address"><button type="button" class="btn ghost sm" data-a="geocode">Find</button></div><small id="geo-out">${a.lat!=null?`Pinned at ${(+a.lat).toFixed(4)}, ${(+a.lon).toFixed(4)}`:"Tap Find to pin it on the map."}</small><input type="hidden" name="lat" value="${a.lat??""}"><input type="hidden" name="lon" value="${a.lon??""}"></div>
 <div class="f"><label>Notes</label><textarea name="note" maxlength="600" placeholder="Opening hours, tips, what to look for">${esc(a.note)}</textarea></div>
 <div class="in2"><div class="f"><label>Cost</label><input name="cost" type="number" step="0.01" min="0" value="${a.cost||""}"></div><div class="f"><label>Currency</label><select name="cur">${["EUR","PLN","CHF","GBP","USD"].map(c=>`<option ${c===a.cur?"selected":""}>${c}</option>`).join("")}</select></div></div>
 <div class="in2"><div class="f"><label>Booking</label><select name="booked"><option value="">Not needed</option><option value="to book" ${a.booked==="to book"?"selected":""}>To book</option><option value="booked" ${a.booked==="booked"?"selected":""}>Booked</option></select></div><div class="f"><label>Day</label><select name="day">${tripDays(t).map(x=>`<option value="${x}" ${x===day?"selected":""}>${fmtDay(x)}</option>`).join("")}</select></div></div>
 <div class="f"><label>Photo (Wikipedia article title, optional)</label><input name="wiki" maxlength="120" value="${esc(a.wiki||"")}" placeholder="Wawel Castle"></div>
 <div class="f"><label>Link (https)</label><input name="link" type="url" maxlength="400" value="${esc(a.link)}" placeholder="https://"></div>
 <div class="acts"><button class="btn" type="submit">Save</button>${id?`<button type="button" class="btn danger" data-a="delact" data-arg="${id}">Delete</button>`:""}</div></form>`)}
