async function geocode(q,cityHint){const tries=[q,cityHint?q+" "+cityHint:null].filter(Boolean);for(const s of tries){try{const r=await fetch("https://geocoding-api.open-meteo.com/v1/search?name="+encodeURIComponent(s)+"&count=1&language=en");if(!r.ok)continue;const j=await r.json();if(j.results&&j.results[0]){const x=j.results[0];return {name:x.name,admin:x.admin1||x.country,lat:x.latitude,lon:x.longitude}}}catch(e){}}return null}

