const wxKey=c=>(+c.lat).toFixed(2)+","+(+c.lon).toFixed(2);
async function loadWx(t,force){const cities=t.cities.filter(c=>c.lat!=null);if(!cities.length)return false;const need=cities.filter(c=>force||!S.wxcache[wxKey(c)]||Date.now()-S.wxcache[wxKey(c)].at>6*36e5);if(!need.length)return false;
 const q="https://api.open-meteo.com/v1/forecast?latitude="+need.map(c=>c.lat).join(",")+"&longitude="+need.map(c=>c.lon).join(",")+"&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,precipitation_sum,snowfall_sum,wind_speed_10m_max,sunrise,sunset&timezone=auto&forecast_days=16";
 try{const r=await fetch(q);if(!r.ok){DIAG.wxErr="HTTP "+r.status;return false}const j=await r.json();const arr=Array.isArray(j)?j:[j];arr.forEach((o,i)=>{const D=o.daily,days={};D.time.forEach((d,n)=>{days[d]={code:D.weather_code[n],max:D.temperature_2m_max[n],min:D.temperature_2m_min[n],pop:D.precipitation_probability_max[n],rain:D.precipitation_sum[n],snow:D.snowfall_sum[n],wind:D.wind_speed_10m_max[n],sunrise:(D.sunrise[n]||"").slice(11,16),sunset:(D.sunset[n]||"").slice(11,16)}});S.wxcache[wxKey(need[i])]={at:Date.now(),days}});save();return true}catch(e){DIAG.wxErr=e.message;return false}}
const DOWL=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];const hm=s=>{const m=/^(\d\d):(\d\d)$/.exec(s||"");return m?+m[1]*60+ +m[2]:null};
const PROFN={in:"Indoors",out:"Outdoors",mix:"In and out"};
const fitLabel=x=>x.out?"Closed":x.s>=80?"Great fit":x.s>=65?"Good fit":x.s>=45?"Fair":"Poor fit";
function rankOptions(t,d){const list=(t.options&&t.options[d])||[];if(!list.length)return[];const city=cityFor(t,d),w=city&&S.wxcache[wxKey(city)]&&S.wxcache[wxKey(city)].days[d];const dow=parseISO(d).getDay(),dd=dayOf(t,d);
 return list.map(o=>{let s=70;const r=[];if(o.closed.includes(dow))return{o,s:0,out:true,r:["Closed on "+DOWL[dow]+"s"]};
  if(o.fixed){s+=30;r.push("Booked slot")}
  if(w){const pop=w.pop??0,wet=pop>=50||(w.rain??0)>=2,snow=(w.snow??0)>0.2,cold=w.max<2,windy=(w.wind??0)>35,clear=w.code<=2;
   if(o.prof==="out"){if(wet){s-=25;r.push("Rain likely "+pop+"%")}else if(pop>=30){s-=8;r.push("Rain possible "+pop+"%")}else{s+=10;r.push("Dry day")}if(snow){s-=o.needs.noSnow?25:10;r.push("Snow forecast")}if(cold){s-=8;r.push("High of "+Math.round(w.max)+"°")}if(windy){s-=6;r.push("Windy")}if(o.needs.clear&&!clear){s-=20;r.push("Cloud hides the view")}}
   else if(o.prof==="mix"){if(wet){s-=10;r.push("Rain likely "+pop+"%")}else if(pop<30){s+=4;r.push("Dry day")}if(snow)s-=4;if(cold)s-=3}
   else{if(wet){s+=18;r.push("Indoors, rain "+pop+"%")}else if(cold){s+=6;r.push("Warm inside")}else r.push("Indoors")}
   const dl=w.sunrise&&w.sunset?(hm(w.sunset)-hm(w.sunrise))/60:8.7;if(o.needs.daylight&&o.hrs+o.tmin/30>dl){s-=12;r.push("Tight for daylight")}}
  else{r.push("No forecast yet");if(o.needs.daylight&&o.hrs+o.tmin/30>8.7){s-=12;r.push("Tight for daylight")}}
  s-=Math.max(0,o.tmin-20)/6;if(o.tmin>=60)r.push(fmtM(o.tmin)+" each way");else if(o.tmin)r.push(o.tmin+" min away");
  const dup=Object.keys(t.days).find(k=>k!==d&&t.days[k].chosen===o.id);if(dup){s-=12;r.unshift("Swaps with "+fmtDay(dup).slice(0,6))}
  return{o,s:Math.max(0,Math.min(100,Math.round(s))),r,cur:o.id===dd.chosen}}).sort((a,b)=>b.s-a.s)}
function useOption(t,d,id){const o=((t.options&&t.options[d])||[]).find(x=>x.id===id);if(!o)return"";const dd=dayOf(t,d),prev=dd.chosen;const put=(day,opt)=>{const x=dayOf(t,day);x.acts=opt.acts.map(a=>Object.assign({},a,{id:uid(),done:false}));x.chosen=opt.id;x.title=opt.name};put(d,o);let msg="";
 const other=Object.keys(t.days).find(k=>k!==d&&t.days[k].chosen===id);if(other&&prev){const po=((t.options&&t.options[other])||[]).find(x=>x.id===prev);if(po){put(other,po);msg=" · "+fmtDay(other).slice(0,6)+" now has "+po.name}}save();return msg}
function wear(d){const o=[],max=d.max,min=d.min,pop=d.pop??0,snow=(d.snow??0)>0.2,wind=d.wind??0;
 o.push(["base",min<2?"Thermal base layer":max<14?"Long-sleeve top":max<22?"T-shirt and a light layer":"T-shirt"]);
 if(max<5)o.push(["mid","Insulated winter jacket over a sweater"]);else if(max<11)o.push(["mid","Warm jacket over a sweater"]);else if(max<17)o.push(["mid","Sweater or light jacket"]);
 if(pop>=50||snow)o.push(["shell","Waterproof jacket or umbrella"]);else if(wind>=30)o.push(["shell","Windproof layer"]);else if(pop>=25)o.push(["shell","Umbrella in the bag"]);
 o.push(["feet",snow||pop>=50?"Waterproof shoes, warm socks":"Comfortable walking shoes"]);
 if(min<6)o.push(["acc","Beanie, gloves and scarf"]);if(d.code<=1&&max>18)o.push(["acc","Sunglasses and sunscreen"]);return o}
function wearNote(d){if((d.snow??0)>0.2)return "Snow possible: cobbles and hills get slippery.";if((d.pop??0)>=60)return "Rain likely: museums in the wettest hours, walks in the drier ones.";if(d.max<=3)return "Properly cold: warm up in a café between sights.";if(d.max>=26)return "Hot: water, shade at midday, sights early.";return "Dry enough for walking."}
