 days.map(d=>{const c=cityFor(t,d);const w=c&&S.wxcache[wxKey(c)]&&S.wxcache[wxKey(c)].days[d];const [txt,ic]=wmo(w?w.code:null);
  return `<div class="wxc"><div class="h">${ICO[ic]}<div><b>${fmtDay(d)}</b><small style="display:block">${esc(c?c.name:"")} · ${w?txt:"beyond the 16-day forecast"}</small></div>${w?`<div class="t num">${Math.round(w.max)}°<small> / ${Math.round(w.min)}°</small></div>`:""}</div>
  ${w?`<div class="stats"><div>Rain<b>${w.pop??0}%</b></div><div>Precip<b>${(w.rain??0).toFixed(1)} mm</b></div><div>Wind<b>${Math.round(w.wind)} km/h</b></div><div>Sunset<b>${esc(w.sunset)}</b></div></div><div class="layers">${wear(w).map(([k,v])=>`<span class="${k}">${esc(v)}</span>`).join("")}</div><small style="display:block;margin-top:8px">${wearNote(w)}</small>`:`<small style="display:block;margin-top:8px">The forecast reaches this date 16 days ahead. Open the app again closer to the trip.</small>`}</div>`}).join("")+
 `<small style="display:block;margin-top:12px">${hasLive?"Forecast by Open-Meteo, updated "+new Date(meta.at).toLocaleString("en-GB",{weekday:"short",hour:"2-digit",minute:"2-digit"})+". Refreshes every 6 hours when online.":"No forecast loaded yet. Open the app once with internet."}</small>`;
