 days.forEach(d=>{const acts=(t.days[d]?t.days[d].acts:[]).filter(a=>a.lat!=null);const pl=[];acts.forEach((a,i)=>{pl.push([a.lat,a.lon]);if(MAPDAY!=="all")b.push([a.lat,a.lon]);const mk=L.marker([a.lat,a.lon],{icon:L.divIcon({className:"",html:`<div class="mk ${a.cat}"><i>${MAPDAY==="all"?"":i+1}</i></div>`,iconSize:[30,30],iconAnchor:[15,30],popupAnchor:[0,-28]})}).bindPopup(`<b>${esc(a.title)}</b><br><small>${esc(fmtDay(d))}${a.t?" · "+esc(a.t):""}</small><br><a href="${esc(gm("",a.place||a.title).replace("origin=&",""))}" target="_blank" rel="noopener noreferrer">Directions</a>`).addTo(MAPLAYER);MAPMK[a.id]=mk;if(MAPDAY!=="all")cards.push({id:a.id,keys:picKeys(a),title:a.title,sub:(a.t?a.t+" · ":"")+CATN[a.cat]+(a.place&&a.place!==a.title?" · "+a.place:""),lat:a.lat,lon:a.lon,zoom:15})});if(MAPDAY!=="all"&&pl.length>1)L.polyline(pl,{color:"#0E7C86",weight:3,opacity:.8}).addTo(MAPLAYER)});
