function mapFocus(btn){const lat=+btn.dataset.lat,lon=+btn.dataset.lon,z=+btn.dataset.zoom;$$(".mapc").forEach(x=>x.classList.toggle("on",x===btn));MAP.flyTo([lat,lon],Math.max(MAP.getZoom(),z),{duration:.6});const mk=MAPMK[btn.dataset.arg];if(mk)setTimeout(()=>mk.openPopup(),650)}

